/*
 * Textarea. Field's recessed
 * well, multi-line. Deliberately the SAME well — a text box that types
 * differently depending on how many lines it holds would be two materials for
 * one job. Composes var(--echo-*) only.
 */
.echo-textarea {
  display: flex;
  flex-direction: column;
  gap: var(--echo-space-4);
}

/* The guarded role, not a wash of --echo-text — see field.css for the why. */
.echo-textarea__label {
  /* Long content wraps rather than pushing its container open. */
  overflow-wrap: anywhere;
  font-family: var(--echo-font-machine, ui-sans-serif, system-ui, sans-serif);
  font-size: var(--echo-text-3xs);
  font-weight: var(--echo-weight-bold, 700);
  letter-spacing: var(--echo-tracking-label, 0.2em);
  text-transform: uppercase;
  color: var(--echo-text-dim);
  transition: color var(--echo-duration-swap) var(--echo-ease-swap);
}
/* The label wakes with its field, as Field's does. */
.echo-textarea:focus-within .echo-textarea__label {
  color: var(--echo-text);
}

.echo-textarea__well {
  padding: var(--echo-space-6) var(--echo-space-8);
  border-radius: var(--echo-radius-xl);
  background: var(--echo-drawn-hollow, linear-gradient(
    160deg,
    color-mix(in oklab, var(--echo-well) 72%, var(--echo-shade-ink, black)),
    color-mix(in oklab, var(--echo-lcd) 88%, var(--echo-shade-ink, black))
  ));
  box-shadow: var(
    --echo-shadow-well,
    inset 0 2px 5px color-mix(in oklab, var(--echo-cast-ink, black) calc(0.6 * var(--echo-shade, 1) * 100%), transparent),
    inset 0 -1px 0 rgb(255 255 255 / calc(0.05 * var(--echo-gloss, 1))),
    inset 0 0 0 var(--echo-line-width, 0px) var(--echo-line, transparent)
  );
  transition: box-shadow var(--echo-duration-swap) ease;
  /* useWellMotion moves the well and sets --well-depth; it never needs
     a transform from here. The floor and the drawn caret sit inside it. */
  position: relative;
  isolation: isolate;
}

/* The floor of the well: shade that deepens as the well is pressed in and
   struck. Nothing at rest, so an idle textarea looks as it always has. */
.echo-textarea__floor {
  position: absolute;
  inset: 0;
  z-index: var(--echo-z-base, 0);
  border-radius: inherit;
  pointer-events: none;
  box-shadow: inset 0 calc(1px + 3px * var(--well-depth, 0)) calc(3px + 8px * var(--well-depth, 0))
    color-mix(in oklab, var(--echo-cast-ink, black) calc(0.3 * var(--echo-shade, 1) * 100%), transparent), inset 0 0 0 var(--echo-line-width, 0px) var(--echo-line, transparent);
  opacity: min(1, var(--well-depth, 0));
}

/* The drawn caret: shown only while useWellMotion is placing it (line by
   line, with a mirror of the text), otherwise the native caret. */
.echo-textarea__caret {
  position: absolute;
  top: 0;
  inset-inline-start: 0;
  z-index: var(--echo-z-top, 2);
  width: 2px;
  border-radius: var(--echo-radius-full);
  background: var(--echo-accent-glow);
  box-shadow: 0 0 6px color-mix(in oklch, var(--echo-accent-glow) 70%, transparent);
  pointer-events: none;
  opacity: 0;
  display: none;
}
.echo-textarea__well[data-caret="drawn"] .echo-textarea__caret {
  display: block;
}
.echo-textarea__well[data-caret="drawn"] .echo-textarea__input {
  caret-color: transparent;
}

.echo-textarea__well:focus-within {
  /* Drawn only in forced colors, which drops the lit inner edge. */
  outline: 2px solid transparent;
  outline-offset: -2px;
  box-shadow:
    /* The ring first, so the well's top shadow doesn't darken it (BUG-17). */
    inset 0 0 0 var(--echo-border-thick, 2px) var(--echo-accent-ink, var(--echo-accent-glow)),
    inset 0 2px 5px color-mix(in oklab, var(--echo-cast-ink, black) calc(0.7 * var(--echo-shade, 1) * 100%), transparent);
}

.echo-textarea__input {
  position: relative;
  z-index: var(--echo-z-raised, 1);
  display: block;
  width: 100%;
  border: 0;
  outline: none;
  padding: 0;
  background: transparent;
  color: var(--echo-text);
  caret-color: var(--echo-accent-glow);
  font-family: var(--echo-font-machine, ui-sans-serif, system-ui, sans-serif);
  font-size: var(--echo-text-md);
  line-height: var(--echo-leading-body, 1.55);
  /*
   * The manual grip fights the autosize measurement — the element would carry
   * an inline height the effect then overwrites on the next keystroke. Vertical
   * space is the component's job here.
   */
  resize: none;
}

.echo-textarea__input--mono {
  font-family: var(--echo-font-mono, ui-monospace, SFMono-Regular, Menlo, monospace);
  font-size: var(--echo-text-md);
}

.echo-textarea__input::placeholder {
  color: var(--echo-text-dim);
}

.echo-textarea[data-disabled] {
  opacity: 0.45;
}
.echo-textarea[data-disabled] .echo-textarea__input {
  cursor: not-allowed;
}

@media (prefers-reduced-motion: reduce) {
  .echo-textarea__well {
    transition: none;
  }
}

/* Coarse-pointer target. Touch only. */
@media (pointer: coarse) {
  .echo-textarea__input {
    min-height: 44px;
  }
}

/*
 * Description and error. Both are linked to the control by Base
 * UI, so a screen reader reads them after the name. The error doesn't rely on
 * hue: it's the words, a square pip (the danger shape Banner uses), and the
 * well's inner edge lit the way focus lights it.
 */
.echo-textarea__description,
.echo-textarea__error {
  margin: 0;
  font-size: var(--echo-text-xs);
  line-height: var(--echo-leading-snug, 1.4);
  overflow-wrap: anywhere;
}
.echo-textarea__description {
  color: var(--echo-text-dim);
}
.echo-textarea__error {
  display: flex;
  gap: var(--echo-space-3);
  align-items: baseline;
  color: var(--echo-text);
}
.echo-textarea__error::before {
  content: "";
  flex-shrink: 0;
  width: 8px;
  height: 8px;
  border-radius: var(--echo-radius-xs);
  background: var(--echo-primary-cap-mid);
  box-shadow: var(--echo-shadow-edge, inset 0 1px 0 rgb(255 255 255 / calc(0.4 * var(--echo-gloss, 1))));
}
.echo-textarea[data-invalid] .echo-textarea__well {
  box-shadow:
    inset 0 2px 5px color-mix(in oklab, var(--echo-cast-ink, black) calc(0.6 * var(--echo-shade, 1) * 100%), transparent),
    inset 0 0 0 1.5px color-mix(in oklch, var(--echo-primary-cap-mid) 80%, transparent),
    inset 0 0 0 var(--echo-line-width, 0px) var(--echo-line, transparent);
}

/*
 * Forced colors (Windows High Contrast) drops the recessed well's gradient and
 * shadows, which is its whole edge: without a border an input, and above all
 * an empty one, isn't visible at all. System colors only, so focus still shows.
 */
@media (forced-colors: active) {
  .echo-textarea__error::before {
    forced-color-adjust: none;
    background: CanvasText;
  }
  .echo-textarea__well {
    border: var(--echo-border-hairline, 1px) solid CanvasText;
  }
  /* The system draws the caret here, in the user's colours. */
  .echo-textarea__caret,
  .echo-textarea__well[data-caret="drawn"] .echo-textarea__caret {
    display: none;
  }
  .echo-textarea__well[data-caret="drawn"] .echo-textarea__input {
    caret-color: auto;
  }
}

"use client";

/**
 * Textarea. Field is
 * single-line; this is the same recessed well, multi-line, and autosizing.
 *
 * AUTOSIZE, and why it is measured rather than computed. Growing a textarea by
 * counting `\n`s is wrong the moment a line wraps, and wrong again at a
 * different width. The honest way is to let the browser lay the text out and
 * read the result: collapse the height, read scrollHeight, set that. It runs on
 * every value change and on resize, and it is cheap because it is one forced
 * reflow of one element.
 *
 * The measurement is skipped entirely when `autosize` is false, so a fixed-rows
 * textarea costs nothing.
 */
import {
  forwardRef,
  useCallback,
  useEffect,
  useImperativeHandle,
  useLayoutEffect,
  useRef,
  useState,
  type ReactNode,
} from "react";
import type { EchoTextInterop } from "echo-ui-core/types";
import { Field as BaseField } from "@base-ui/react/field";
import { useWellMotion } from "echo-ui-core/tactile";
import "./textarea.css";

/**
 * Layout effects warn during SSR because there is no layout to run them
 * against. The measurement genuinely has to happen before paint on the client
 * (otherwise the box visibly jumps from one row to its real height), so the
 * hook is swapped rather than the behavior.
 */
const useIsomorphicLayoutEffect = typeof window !== "undefined" ? useLayoutEffect : useEffect;

/**
 * Narrowed deliberately.
 *
 * This used to extend `TextareaHTMLAttributes` wholesale and accept
 * `className` — an open API, and the one `PRINCIPLES.md` now says Echo does
 * not have. It was also half of a backwards split: the control that most
 * needed a form library could be restyled per-instance, while `Checkbox`
 * could not even take an `onBlur`. It now takes the same declared interop set
 * as every other text control, and nothing else.
 */
interface TextareaOwnProps extends EchoTextInterop {
  /** Help text under the textarea, linked to it so a screen reader reads it after the name. */
  description?: ReactNode;
  /**
   * What's wrong, in words. While it's set the textarea is invalid: the
   * message shows under it with a square pip, the textarea gets
   * `aria-invalid`, and the message is linked to it. Clear it when fixed.
   */
  error?: string;
  /** Visible eyebrow label; also the accessible name. */
  value?: string;
  defaultValue?: string;
  onValueChange?: (value: string) => void;
  /** Render the value in the machine (mono) voice — logs, patch notes, codes. */
  mono?: boolean;
  /** Grow to fit the content instead of scrolling. Default true. */
  autosize?: boolean;
  /** Rows to show before growing. Also the fixed height when autosize is off. */
  rows?: number;
  /** Stop growing here and scroll instead. Rows, not pixels. */
  maxRows?: number;
}

/**
 * A field has to have a name. A visible `label` is
 * the one to reach for; `aria-label` or `aria-labelledby` are for a field whose
 * label is elsewhere on screen. Leaving all three out is a type error.
 */
type FieldName =
  | { label: string; "aria-label"?: string; "aria-labelledby"?: string }
  | { "aria-label": string; label?: string; "aria-labelledby"?: string }
  | { "aria-labelledby": string; label?: string; "aria-label"?: string };

export type TextareaProps = TextareaOwnProps & FieldName;

/**
 * `forwardRef`, not a `ref` prop — see the note on `Field`. The caller's
 * ref is merged with the one autosize already needs, and points at the
 * textarea itself.
 */
export const Textarea = forwardRef<HTMLTextAreaElement, TextareaProps>(function Textarea(
  {
  label,
  value,
  defaultValue,
  onValueChange,
  mono = false,
  autosize = true,
  rows = 3,
  maxRows,
  disabled,
  name,
  description,
  error,
  "aria-label": ariaLabel,
  "aria-labelledby": ariaLabelledby,
  "aria-describedby": ariaDescribedby,
  ...interop
  },
  forwardedRef,
) {
  const ref = useRef<HTMLTextAreaElement>(null);
  // Autosize measures through `ref`; the caller is handed the same node.
  useImperativeHandle(forwardedRef, () => ref.current as HTMLTextAreaElement, []);

  // The well answers the hand (useWellMotion), as Field's does: pressed in
  // on click, struck by each key, with a caret that glides along the line.
  const well = useWellMotion<HTMLDivElement>();

  // Uncontrolled values still have to be measured, so the current text is
  // tracked here regardless of who owns it.
  const [innerValue, setInnerValue] = useState(defaultValue ?? "");
  const text = value ?? innerValue;

  const resize = useCallback(() => {
    const el = ref.current;
    if (!el || !autosize) return;

    // Collapse first: scrollHeight only shrinks if the box is smaller than the
    // content, so measuring without this makes the field grow and never shrink.
    el.style.height = "auto";
    const styles = getComputedStyle(el);
    const lineHeight = parseFloat(styles.lineHeight) || 20;
    const vertical = parseFloat(styles.paddingTop) + parseFloat(styles.paddingBottom);
    const cap = maxRows ? maxRows * lineHeight + vertical : Infinity;
    const next = Math.min(el.scrollHeight, cap);

    el.style.height = `${next}px`;
    el.style.overflowY = el.scrollHeight > cap ? "auto" : "hidden";
  }, [autosize, maxRows]);

  useIsomorphicLayoutEffect(resize, [text, resize]);

  // A width change re-wraps the text, which changes the height. Without this
  // the box is correct until the first time the window moves.
  useEffect(() => {
    if (!autosize || typeof ResizeObserver === "undefined") return;
    const el = ref.current;
    if (!el) return;
    const observer = new ResizeObserver(resize);
    observer.observe(el);
    return () => observer.disconnect();
  }, [autosize, resize]);

  // Base UI's Field wires the label, description, error and aria-invalid;
  // Echo keeps the autosize and the look.
  return (
    <BaseField.Root
      className="echo-textarea"
      disabled={disabled}
      invalid={error ? true : undefined}
      name={name}
    >
      {label && <BaseField.Label className="echo-textarea__label">{label}</BaseField.Label>}
      <div className="echo-textarea__well" ref={well}>
        <span className="echo-textarea__floor" data-echo-floor aria-hidden />
        <BaseField.Control
          ref={ref}
          value={text}
          onValueChange={(next) => {
            if (value === undefined) setInnerValue(next);
            onValueChange?.(next);
          }}
          className={mono ? "echo-textarea__input echo-textarea__input--mono" : "echo-textarea__input"}
          // A visible label wins; these only apply when there is none.
          aria-label={label ? undefined : ariaLabel}
          aria-labelledby={label ? undefined : ariaLabelledby}
          aria-describedby={ariaDescribedby}
          render={<textarea {...interop} rows={rows} />}
        />
        <span className="echo-textarea__caret" data-echo-caret aria-hidden />
      </div>
      {description != null && (
        <BaseField.Description className="echo-textarea__description">{description}</BaseField.Description>
      )}
      {error && (
        <BaseField.Error className="echo-textarea__error" match>
          {error}
        </BaseField.Error>
      )}
    </BaseField.Root>
  );
});
